     1	/**
     2	 * Organization rows plus slug uniqueness lookups.
     3	 *
     4	 * Must call (do not reimplement): archivePatch, uniqueSlug
     5	 */
     6	import { and, eq, isNull, like } from "drizzle-orm";
     7	import { newId } from "@/lib/id";
     8	import { uniqueSlug } from "@/lib/slug";
     9	import { archivePatch } from "@/lib/soft-delete";
    10	import { getDb, members, organizations } from "@/server/db";
    11	import { toIsoTimestamp } from "@/types/common";
    12	import { toOrganization } from "./_mappers";
    13	import type {
    14	  CreateOrganizationInput,
    15	  UpdateOrganizationInput,
    16	} from "@/schemas/organization";
    17	import type { OrgId, UserId } from "@/types/common";
    18	import type { Organization } from "@/types/organization";
    19	
    20	export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
    21	  const row = getDb()
    22	    .select()
    23	    .from(organizations)
    24	    .where(eq(organizations.id, orgId))
    25	    .get();
    26	  return row ? toOrganization(row) : null;
    27	}
    28	
    29	export async function findOrgBySlug(slug: string): Promise<Organization | null> {
    30	  const row = getDb()
    31	    .select()
    32	    .from(organizations)
    33	    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    34	    .get();
    35	  return row ? toOrganization(row) : null;
    36	}
    37	
    38	/** Every org the user still holds a live membership in. */
    39	export async function listOrgsForUser(
    40	  userId: UserId,
    41	): Promise<readonly Organization[]> {
    42	  const rows = getDb()
    43	    .select({ org: organizations })
    44	    .from(members)
    45	    .innerJoin(organizations, eq(organizations.id, members.orgId))
    46	    .where(
    47	      and(
    48	        eq(members.userId, userId),
    49	        isNull(members.archivedAt),
    50	        isNull(organizations.archivedAt),
    51	      ),
    52	    )
    53	    .all();
    54	
    55	  return rows.map((row) => toOrganization(row.org));
    56	}
    57	
    58	/**
    59	 * Creates the org row. The slug is de-duplicated here rather than in the
    60	 * service so a race on the unique index still resolves to a usable slug.
    61	 */
    62	export async function insertOrg(
    63	  input: CreateOrganizationInput,
    64	  ownerId: UserId,
    65	): Promise<Organization> {
    66	  const taken = await listTakenOrgSlugs(input.slug);
    67	  const slug = uniqueSlug(input.slug, taken);
    68	  const stamp = toIsoTimestamp(new Date());
    69	
    70	  const row = getDb()
    71	    .insert(organizations)
    72	    .values({
    73	      id: newId(),
    74	      name: input.name,
    75	      slug,
    76	      ownerId,
    77	      plan: input.plan,
    78	      logoUrl: null,
    79	      trialEndsAt: null,
    80	      createdAt: stamp,
    81	      updatedAt: stamp,
    82	    })
    83	    .returning()
    84	    .get();
    85	
    86	  return toOrganization(row);
    87	}
    88	
    89	/**
    90	 * Settings and profile patch. `slug` is accepted for the "change workspace
    91	 * URL" form: the form validates the slug with `slugSchema` before it gets
    92	 * here, so the column is written as given.
    93	 */
    94	export async function updateOrg(
    95	  orgId: OrgId,
    96	  patch: UpdateOrganizationInput & { readonly slug?: string },
    97	): Promise<Organization> {
    98	  const current = await findOrgById(orgId);
    99	  if (!current) throw new Error(`Organization ${orgId} not found`);
   100	
   101	  const settings = { ...current.settings, ...(patch.settings ?? {}) };
   102	
   103	  const row = getDb()
   104	    .update(organizations)
   105	    .set({
   106	      ...(patch.name === undefined ? {} : { name: patch.name }),
   107	      ...(patch.slug === undefined ? {} : { slug: patch.slug }),
   108	      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
   109	      defaultIssueStatus: settings.defaultIssueStatus,
   110	      allowPublicProjects: settings.allowPublicProjects,
   111	      requireTwoFactor: settings.requireTwoFactor,
   112	      digestHourUtc: settings.digestHourUtc,
   113	      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
   114	      updatedAt: toIsoTimestamp(new Date()),
   115	    })
   116	    .where(eq(organizations.id, orgId))
   117	    .returning()
   118	    .get();
   119	
   120	  return toOrganization(row);
   121	}
   122	
   123	export async function archiveOrg(orgId: OrgId): Promise<Organization> {
   124	  const row = getDb()
   125	    .update(organizations)
   126	    .set(archivePatch())
   127	    .where(eq(organizations.id, orgId))
   128	    .returning()
   129	    .get();
   130	
   131	  if (!row) throw new Error(`Organization ${orgId} not found`);
   132	  return toOrganization(row);
   133	}
   134	
   135	/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
   136	export async function listTakenOrgSlugs(
   137	  prefix: string,
   138	): Promise<readonly string[]> {
   139	  const rows = getDb()
   140	    .select({ slug: organizations.slug })
   141	    .from(organizations)
   142	    .where(like(organizations.slug, `${prefix}%`))
   143	    .all();
   144	  return rows.map((row) => row.slug);
   145	}
