/**
 * Renames an organization and retires the slug it gives up, in one
 * transaction. The slug is refused while another workspace holds it as its
 * current slug (live or archived) or still holds it retired. The workspace's
 * own retirement of `to` is consumed, which ends that retirement.
 *
 * Returns the slug it replaced alongside the workspace as stored afterwards.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  to: string,
): Promise<{ readonly from: string; readonly organization: Organization }> {
  const now = new Date();
  const stamp = toIsoTimestamp(now);

  return getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) throw new Error(`Organization ${orgId} not found`);

    const currentHolder = tx
      .select({ id: organizations.id })
      .from(organizations)
      .where(eq(organizations.slug, to))
      .get();
    const heldByOther = tx
      .select({ id: organizationRetiredSlugs.id })
      .from(organizationRetiredSlugs)
      .where(
        and(
          eq(organizationRetiredSlugs.slug, to),
          ne(organizationRetiredSlugs.orgId, orgId),
          gt(organizationRetiredSlugs.retiredAt, holdStart(now)),
        ),
      )
      .get();
    if (currentHolder || heldByOther) {
      throw new InvalidSlugError(to, "is not available");
    }

    // Clears this workspace's own retirement of `to`, and any lapsed hold on it.
    tx.delete(organizationRetiredSlugs)
      .where(eq(organizationRetiredSlugs.slug, to))
      .run();

    const row = tx
      .update(organizations)
      .set({ slug: to, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    tx.insert(organizationRetiredSlugs)
      .values({
        id: newId(),
        orgId,
        slug: current.slug,
        retiredAt: stamp,
      })
      .run();

    return { from: current.slug, organization: toOrganization(row) };
  });
}

/**
 * Feeds `uniqueSlug()`. Covers current slugs and slugs still held retired, so a
 * derived slug never lands on one; matching on the prefix keeps the scan small.
 */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const current = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();

  const retired = getDb()
    .select({ slug: organizationRetiredSlugs.slug })
    .from(organizationRetiredSlugs)
    .where(
      and(
        like(organizationRetiredSlugs.slug, `${prefix}%`),
        gt(organizationRetiredSlugs.retiredAt, holdStart(new Date())),
      ),
    )
    .all();

  return [...current, ...retired].map((row) => row.slug);
}

