    expect((await resolveOrgBySlug("rn-chain-b"))?.id).toBe(tenant.org.id);
    expect((await resolveOrgBySlug("rn-chain-c"))?.id).toBe(tenant.org.id);
  });

  it("releases the old slug exactly ORG_SLUG_HOLD_DAYS after the rename", async () => {
    const tenant = await createTenant("rn-release");
    const taker = await createTenant("rn-release-taker");
    await rename(tenant, "rn-release-new");

    vi.setSystemTime(new Date(START.getTime() + ORG_SLUG_HOLD_DAYS * DAY_MS - 1));
    expect((await resolveOrgBySlug("rn-release"))?.id).toBe(tenant.org.id);
    await expect(rename(taker, "rn-release")).rejects.toBeInstanceOf(InvalidSlugError);

    vi.setSystemTime(new Date(START.getTime() + ORG_SLUG_HOLD_DAYS * DAY_MS));
    expect(await resolveOrgBySlug("rn-release")).toBeNull();
    const taken = await rename(taker, "rn-release");
    expect(taken.slug).toBe("rn-release");
    expect((await resolveOrgBySlug("rn-release"))?.id).toBe(taker.org.id);
  });
});
